          "text": "{\"snapshotId\":\"capture-a52f5d38-a274-4653-a48f-d69c1c23685d\",\"url\":\"https://nodejs.org/api/fs.html\",\"title\":\"File system | Node.js v26.11.1 Documentation\",\"text\":\" patterns are tested against the filename, and functions receive the filename and return true to ignore. Default: undefined.\\nReturns: <AsyncIterator> of objects with the properties:\\neventType <string> The type of change\\nfilename <string> | <Buffer> | <null> The name of the file changed.\\n\\nReturns an async iterator that watches for changes on filename, where filename is either a file or a directory.\\n\\nconst { watch } = require('node:fs/promises');\\n\\nconst ac = new AbortController();\\nconst { signal } = ac;\\nsetTimeout(() => ac.abort(), 10000);\\n\\n(async () => {\\n  try {\\n    const watcher = watch(__filename, { signal });\\n    for await (const event of watcher)\\n      console.log(event);\\n  } catch (err) {\\n    if (err.name === 'AbortError')\\n      return;\\n    throw err;\\n  }\\n})();\\n\\nJS\\nCOPY\\n\\nOn most platforms, 'rename' is emitted whenever a filename appears or disappears in the directory.\\n\\nAll the caveats for fs.watch() also apply to fsPromises.watch().\\n\\nfsPromises.writeFile(file, data[, options])\\n#\\nAdded in: v10.0.0\\nHistory\\nfile <string> | <Buffer> | <URL> | <FileHandle> filename or FileHandle\\ndata <string> | <Buffer> | <TypedArray> | <DataView> | <AsyncIterable> | <Iterable>\\noptions <Object> | <string>\\nencoding <string> | <null> Default: 'utf8'\\nmode <integer> Default: 0o666\\nflag <string> See support of file system flags. Default: 'w'.\\nflush <boolean> If all data is successfully written to the file, and flush is true, filehandle.sync() is used to flush the data. Default: false.\\nsignal <AbortSignal> allows aborting an in-progress writeFile\\nReturns: <Promise> Fulfills with undefined upon success.\\n\\nAsynchronously writes data to a file, replacing the file if it already exists. data can be a string, a buffer, an <AsyncIterable>, or an <Iterable> object.\\n\\nThe encoding option is ignored if data is a buffer.\\n\\nIf options is a string, then it specifies the encoding.\\n\\nThe mode option only affects the newly created file. See fs.open() for more details.\\n\\nAny specified <FileHandle> has to support writing.\\n\\nIt is unsafe to use fsPromises.writeFile() multiple times on the same file without waiting for the promise to be settled.\\n\\nSimilarly to fsPromises.readFile - fsPromises.writeFile is a convenience method that performs multiple write calls internally to write the buffer passed to it. For performance sensitive code consider using fs.createWriteStream() or filehandle.createWriteStream().\\n\\nIt is possible to use an <AbortSignal> to cancel an fsPromises.writeFile(). Cancelation is \\\"best effort\\\", and some amount of data is likely still to be written.\\n\\nimport { writeFile } from 'node:fs/promises';\\nimport { Buffer } from 'node:buffer';\\n\\ntry {\\n  const controller = new AbortController();\\n  const { signal } = controller;\\n  const data = new Uint8Array(Buffer.from('Hello Node.js'));\\n  const promise = writeFile('message.txt', data, { signal });\\n\\n  // Abort the request before the promise settles.\\n  controller.abort();\\n\\n  await promise;\\n} catch (err) {\\n  // When a request is aborted - err is an AbortError\\n  console.error(err);\\n}\\n\\nMJS\\nCOPY\\n\\nAborting an ongoing request does not abort individual operating system requests but rather the internal buffering fs.writeFile performs.\\n\\nfsPromises.constants\\n#\\nAdded in: v18.4.0, v16.17.0\\nType: <Object>\\n\\nReturns an object containing commonly used constants for file system operations. The object is the same as fs.constants. See FS constants for more details.\\n\\nCallback API\\n#\\n\\nThe callback APIs perform all operations asynchronously, without blocking the event loop, then invoke a callback function upon completion or error.\\n\\nThe callback APIs use the underlying Node.js threadpool to perform file system operations off the event loop thread. These operations are not synchronized or threadsafe. Care must be taken when performing multiple concurrent modifications on the same file or data corruption may occur.\\n\\nfs.access(path[, mode], callback)\\n#\\nAdded in: v0.11.15\\nHistory\\npath <string> | <Buffer> | <URL>\\nmode <integer> Default: fs.constants.F_OK\\ncallback <Function>\\nerr <Error>\\n\\nTests a user's permissions for the file or directory specified by path. The mode argument is an optional integer that specifies the accessibility checks to be performed. mode should be either the value fs.constants.F_OK or a mask consisting of the bitwise OR of any of fs.constants.R_OK, fs.constants.W_OK, and fs.constants.X_OK (e.g. fs.constants.W_OK | fs.constants.R_OK). Check File access constants for possible values of mode.\\n\\nThe final argument, callback, is a callback function that is invoked with a possible error argument. If any of the accessibility checks fail, the error argument will be an Error object. The following examples check if package.json exists, and if it is readable or writable.\\n\\nimport { access, constants } from 'node:fs';\\n\\nconst file = 'package.json';\\n\\n// Check if the file exists in the current directory.\\naccess(file, constants.F_OK, (err) => {\\n  console.log(`${file} ${err ? 'does not exist' : 'exists'}`);\\n});\\n\\n// Check if the file is readable.\\naccess(file, constants.R_OK, (err) => {\\n  console.log(`${file} ${err ? 'is not readable' : 'is readable'}`);\\n});\\n\\n// Check if the file is writable.\\naccess(file, constants.W_OK, (err) => {\\n  console.log(`${file} ${err ? 'is not writable' : 'is writable'}`);\\n});\\n\\n// Check if the file is readable and writable.\\naccess(file, constants.R_OK | constants.W_OK, (err) => {\\n  console.log(`${file} ${err ? 'is not' : 'is'} readable and writable`);\\n});\\n\\nMJS\\nCOPY\\n\\nDo not use fs.access() to check for the accessibility of a file before calling fs.open(), fs.readFile(), or fs.writeFile(). Doing so introduces a race condition, since other processes may change the file's state between the two calls. Instead, user code should open/read/write the file directly and handle the error raised if the file is not accessible.\\n\\nwrite (NOT RECOMMENDED)\\n\\nimport { access, open, close } from 'node:fs';\\n\\naccess('myfile', (err) => {\\n  if (!err) {\\n    console.error('myfile already exists');\\n    return;\\n  }\\n\\n  open('myfile', 'wx', (err, fd) => {\\n    if (err) throw err;\\n\\n    try {\\n      writeMyData(fd);\\n    } finally {\\n      close(fd, (err) => {\\n        if (err) throw err;\\n      });\\n    }\\n  });\\n});\\n\\nMJS\\nCOPY\\n\\nwrite (RECOMMENDED)\\n\\nimport { open, close } from 'node:fs';\\n\\nopen('myfile', 'wx', (err, fd) => {\\n  if (err) {\\n    if (err.code === 'EEXIST') {\\n      console.error('myfile already exists');\\n      return;\\n    }\\n\\n    throw err;\\n  }\\n\\n  try {\\n    writeMyData(fd);\\n  } finally {\\n    close(fd, (err) => {\\n      if (err) throw err;\\n    });\\n  }\\n});\\n\\nMJS\\nCOPY\\n\\nread (NOT RECOMMENDED)\\n\\nimport { access, open, close } from 'node:fs';\\naccess('myfile', (err) => {\\n  if (err) {\\n    if (err.code === 'ENOENT') {\\n      console.error('myfile does not exist');\\n      return;\\n    }\\n\\n    throw err;\\n  }\\n\\n  open('myfile', 'r', (err, fd) => {\\n    if (err) throw err;\\n\\n    try {\\n      readMyData(fd);\\n    } finally {\\n      close(fd, (err) => {\\n        if (err) throw err;\\n      });\\n    }\\n  });\\n});\\n\\nMJS\\nCOPY\\n\\nread (RECOMMENDED)\\n\\nimport { open, close } from 'node:fs';\\n\\nopen('myfile', 'r', (err, fd) => {\\n  if (err) {\\n    if (err.code === 'ENOENT') {\\n      console.error('myfile does not exist');\\n      return;\\n    }\\n\\n    throw err;\\n  }\\n\\n  try {\\n    readMyData(fd);\\n  } finally {\\n    close(fd, (err) => {\\n      if (err) throw err;\\n    });\\n  }\\n});\\n\\nMJS\\nCOPY\\n\\nThe \\\"not recommended\\\" examples above check for accessibility and then use the file; the \\\"recommended\\\" examples are better because they use the file directly and handle the error, if any.\\n\\nIn general, check for the accessibility of a file only if the file will not be used directly, for example when its accessibility is a signal from another process.\\n\\nOn Windows, access-control policies (ACLs) on a directory may limit access to a file or directory. The fs.access() function, however, does not check the ACL and therefore may report that a path is accessible even if the ACL restricts the user from reading or writing to it.\\n\\nfs.appendFile(path, data[, options], callback)\\n#\\nAdded in: v0.6.7\\nHistory\\npath <string> | <Buffer> | <URL> | <number> filename or file descriptor\\ndata <string> | <Buffer>\\noptions <Object> | <string>\\nenc\",\"links\":[{\"url\":\"https://nodejs.org/api/fs.html\",\"label\":\"#\"},{\"url\":\"https://github.com/nodejs/node/blob/main/lib/fs.js\",\"label\":\"lib/fs.js\"},{\"url\":\"https://nodejs.org/api/documentation.html\",\"label\":\"Stability: 2\"},{\"url\":\"https://nodejs.org/api/events.html\",\"label\":\"<EventEmitter>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Data_structures\",\"label\":\"<string>\"},{\"url\":\"https://nodejs.org/api/buffer.html\",\"label\":\"<Buffer>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/TypedArray\",\"label\":\"<TypedArray>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/DataView\",\"label\":\"<DataView>\"},{\"url\":\"https://tc39.github.io/ecma262/\",\"label\":\"<AsyncIterable>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Iteration_protocols\",\"label\":\"<Iterable>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Object\",\"label\":\"<Object>\"},{\"url\":\"https://nodejs.org/api/globals.html\",\"label\":\"<AbortSignal>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise\",\"label\":\"<Promise>\"},{\"url\":\"http://man7.org/linux/man-pages/man2/chmod.2.html\",\"label\":\"chmod(2)\"},{\"url\":\"http://man7.org/linux/man-pages/man2/chown.2.html\",\"label\":\"chown(2)\"},{\"url\":\"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Number/MAX_SAFE_INTEGER\",\"label\":\"Number.MAX_SAFE_INTEGER\"},{\"url\":\"https://nodejs.org/api/stream.html\",\"label\":\"stream.getDefaultHighWaterMark()\"},{\"url\":\"http://man7.org/linux/man-pages/man2/fdatasync.2.html\",\"label\":\"fdatasync(2)\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Function\",\"label\":\"<Function>\"},{\"url\":\"https://nodejs.org/api/stream_iter.html\",\"label\":\"stream/iter pull()\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Uint8Array\",\"label\":\"<Uint8Array>\"}],\"outline\":\"File system #\\nPromise example #\\nCallback example #\\nSynchronous example #\\nPromises API #\\nClass: FileHandle #\\nfsPromises.access(path[, mode]) #\\nfsPromises.appendFile(path, data[, options]) #\\nfsPromises.chmod(path, mode) #\\nfsPromises.chown(path, uid, gid) #\\nfsPromises.copyFile(src, dest[, mode]) #\\nfsPromises.cp(src, dest[, options]) #\\nfsPromises.glob(pattern[, options]) #\\nfsPromises.lchmod(path, mode) #\\nfsPromises.lchown(path, uid, gid) #\\nfsPromises.lutimes(path, atime, mtime) #\\nfsPromises.link(existingPath, newPath) #\\nfsPromises.lstat(path[, options]) #\\nfsPromises.mkdir(path[, options]) #\\nfsPromises.mkdtemp(prefix[, options]) #\\nfsPromises.mkdtempDisposable(prefix[, options]) #\\nfsPromises.open(path, flags[, mode]) #\\nfsPromises.opendir(path[, options]) #\\nfsPromises.readdir(path[, options]) #\\nfsPromises.readFile(path[, options]) #\\nfsPromises.readlink(path[, options]) #\\nfsPromises.realpath(path[, options]) #\\nfsPromises.rename(oldPath, newPath) #\\nfsPromises.rmdir(path[, options]) #\\nfsPromises.rm(path[, options]) #\\nfsPromises.stat(path[, options]) #\\nfsPromises.statfs(path[, options]) #\\nfsPromises.symlink(target, path[, type]) #\\nfsPromises.truncate(path[, len]) #\\nfsPromises.unlink(path) #\\nfsPromises.utimes(path, atime, mtime) #\\nfsPromises.watch(filename[, options]) #\\nfsPromises.writeFile(file, data[, options]) #\\nfsPromises.constants #\\nCallback API #\\nfs.access(path[, mode], callback) #\\nfs.appendFile(path, data[, options], callback) #\\nfs.chmod(path, mode, callback) #\\nfs.chown(path, uid, gid, callback) #\\nfs.close(fd[, callback]) #\\nfs.copyFile(src, dest[, mode], callback) #\\nfs.cp(src, dest[, options], callback) #\\nfs.createReadStream(path[, options]) #\\nfs.createWriteStream(path[, options]) #\\nfs.exists(path, callback) #\\nfs.fchmod(fd, mode, callback) #\\nfs.fchown(fd, uid, gid, callback) #\\nfs.fdatasync(fd, callback) #\\nfs.fstat(fd[, options], callback) #\\nfs.fsync(fd, callback) #\\nfs.ftruncate(fd[, len], callback) #\\nfs.futimes(fd, atime, mtime, callback) #\\nfs.glob(pattern[, options], callback) #\\nfs.lchmod(path, mode, callback) #\\nfs.l\",\"segmentIndex\":7,\"segmentCount\":26,\"truncated\":true,\"captureTruncated\":false,\"httpStatus\":200}"
