');\\n    const contents = await readFile(filePath, { encoding: 'utf8' });\\n    console.log(contents);\\n  } catch (err) {\\n    console.error(err.message);\\n  }\\n}\\nlogFile();\\n\\nJAVASCRIPT\\nCOPY\\n\\nIt is possible to abort an ongoing readFile using an <AbortSignal>. If a request is aborted the promise returned is rejected with an AbortError:\\n\\nimport { readFile } from 'node:fs/promises';\\n\\ntry {\\n  const controller = new AbortController();\\n  const { signal } = controller;\\n  const promise = readFile(fileName, { signal });\\n\\n  // Abort the request before the promise settles.\\n  controller.abort();\\n\\n  await promise;\\n} catch (err) {\\n  // When a request is aborted - err is an AbortError\\n  \",\"links\":[{\"url\":\"https://nodejs.org/api/fs.html\",\"label\":\"#\"},{\"url\":\"https://github.com/nodejs/node/blob/main/lib/fs.js\",\"label\":\"lib/fs.js\"},{\"url\":\"https://nodejs.org/api/documentation.html\",\"label\":\"Stability: 2\"},{\"url\":\"https://nodejs.org/api/events.html\",\"label\":\"<EventEmitter>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Data_structures\",\"label\":\"<string>\"},{\"url\":\"https://nodejs.org/api/buffer.html\",\"label\":\"<Buffer>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/TypedArray\",\"label\":\"<TypedArray>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/DataView\",\"label\":\"<DataView>\"},{\"url\":\"https://tc39.github.io/ecma262/\",\"label\":\"<AsyncIterable>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Iteration_protocols\",\"label\":\"<Iterable>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Object\",\"label\":\"<Object>\"},{\"url\":\"https://nodejs.org/api/globals.html\",\"label\":\"<AbortSignal>\"},{\"url\":\"https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Promise\",\"label\":\"<Promise>\"},{\"url\":